import { Group, PointLight } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [meshUrl]
 * @property {Array<{name:string, params:any, trigger:string}>} [cinematicPrimitives]
 * @property {Array<any>} [textContent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{loadTexture(url:string):Promise<any>}} textureLoader
 * @property {{loadGLB(url:string):Promise<any>}} glbLoader
 * @property {{loadVideo?(url:string):Promise<any>}} videoLoader
 * @property {{createText(content:string, opts?:any):any}} fontAtlas
 * @property {{[key:string]:(target:any, params:any)=>{timeline:any, cleanup:()=>void}}} primitives
 * @property {(event:string,payload:any)=>void} emit
 * @property {string} [tier]
 */

/**
 * Creates a badge node for the Journal hub.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group: ThreeGroup, PointLight: ThreePointLight } = ctx.THREE;

  // container for everything
  const root = new ThreeGroup();

  // store references for cleanup
  let loadedMesh = null;
  const materialSet = new Set();
  let hoverTimeline = null;
  const primitiveInstances = [];

  // ---------- Load GLB ----------
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      // gltf.scene is assumed to be an Object3D hierarchy
      loadedMesh = gltf.scene;
      root.add(loadedMesh);

      // collect materials for later disposal
      loadedMesh.traverse((obj) => {
        if (obj.isMesh && obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => materialSet.add(m));
          } else {
            materialSet.add(obj.material);
          }
        }
      });
    });
  }

  // ---------- Accent Rim Light ----------
  const accentColor = config.colors?.accent ?? '#ff2a38';
  const rimLight = new ThreePointLight(accentColor, 0.8, 5);
  rimLight.position.set(0, 0, 1.2); // slight offset towards camera
  root.add(rimLight);

  // ---------- Cinematic Primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const instance = ctx.primitives[prim.name]
        ? ctx.primitives[prim.name](root, prim.params || {})
        : null;
      if (instance) {
        primitiveInstances.push(instance);
      }
    });
  }

  // ---------- Interaction Handlers ----------
  function onHover() {
    // Create or restart the rise‑in animation (y +0.15 → original)
    // Capture the current base Y so we can always return relative to it
    const baseY = root.position.y;
    if (!hoverTimeline) {
      hoverTimeline = gsap.timeline({ paused: true })
        .to(
          root.position,
          {
            y: baseY + 0.15,
            duration: 0.7,
            ease: 'power3.out',
          },
          0,
        )
        .to(
          root.position,
          {
            y: baseY,
            duration: 0.3,
            ease: 'power2.in',
          },
          '+=0.1',
        );
    } else {
      hoverTimeline.restart();
    }
  }

  function onClick() {
    ctx.emit('hub-journal.select', {});
  }

  // expose handlers for external event system
  root.userData.handlers = {
    hover: onHover,
    click: onClick,
  };

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // dispose loaded geometry / materials
    if (loadedMesh) {
      loadedMesh.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) {
            obj.geometry.dispose();
          }
        }
      });
    }
    materialSet.forEach((mat) => {
      // dispose texture maps if present
      ['map', 'roughnessMap', 'metalnessMap', 'normalMap', 'emissiveMap', 'alphaMap'].forEach(
        (prop) => {
          if (mat[prop]) {
            mat[prop].dispose();
          }
        },
      );
      if (mat.dispose) mat.dispose();
    });
    // kill GSAP timeline
    if (hoverTimeline) {
      hoverTimeline.kill();
      hoverTimeline = null;
    }
    // cleanup primitives
    primitiveInstances.forEach((inst) => {
      if (inst.cleanup) inst.cleanup();
    });
    // remove handlers reference
    root.userData.handlers = {};
  };

  return root;
}
